(function () {
  function isDesktopServicesMega() {
    return (
      typeof window.matchMedia === 'function' && window.matchMedia('(min-width: 992px)').matches
    );
  }

  function initServicesMegaTabs() {
    var root = document.querySelector('[data-services-mega]');
    if (!root || root.dataset.servicesMegaInit === '1') return;
    root.dataset.servicesMegaInit = '1';

    var tabs = root.querySelectorAll('[data-services-tab]');
    var panels = root.querySelectorAll('[data-services-panel]');
    if (!tabs.length || !panels.length) return;

    function setActive(index) {
      tabs.forEach(function (tab, i) {
        var on = i === index;
        tab.classList.toggle('is-active', on);
        tab.setAttribute('aria-selected', on ? 'true' : 'false');
        tab.tabIndex = on ? 0 : -1;
      });
      panels.forEach(function (panel, i) {
        var on = i === index;
        panel.classList.toggle('is-active', on);
        panel.setAttribute('aria-hidden', on ? 'false' : 'true');
      });
    }

    function syncLayout() {
      if (isDesktopServicesMega()) {
        panels.forEach(function (p) {
          p.classList.add('is-active');
          p.setAttribute('aria-hidden', 'false');
        });
      } else {
        var activeTab = root.querySelector('.services-mega__cat.is-active');
        var idx = activeTab
          ? parseInt(activeTab.getAttribute('data-services-tab') || '0', 10)
          : 0;
        setActive(idx);
      }
    }

    tabs.forEach(function (tab) {
      tab.addEventListener('click', function () {
        if (isDesktopServicesMega()) return;
        var i = parseInt(tab.getAttribute('data-services-tab') || '0', 10);
        setActive(i);
      });
    });

    window.addEventListener('resize', syncLayout);
    syncLayout();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initServicesMegaTabs);
  } else {
    initServicesMegaTabs();
  }
  window.addEventListener('bootstrapScriptLoaded', initServicesMegaTabs);
})();

// Handle Packages menu navigation and dropdown
(function () {
  function initPackagesMenu() {
    const packagesLink = document.getElementById('nav-link-packages-level-0');
    if (!packagesLink) return;

    const packagesText = packagesLink.querySelector('.packages-link-text');
    const caretIcon = packagesLink.querySelector('.packages-dropdown-toggle');

    // Click on "Packages" text -> navigate to /package
    if (packagesText) {
      packagesText.addEventListener('click', (e) => {
        e.stopPropagation();
        e.preventDefault();
        window.location.href = '/package';
      });
    }

    // Click on caret -> toggle dropdown (prevent navigation)
    if (caretIcon) {
      caretIcon.addEventListener('click', (e) => {
        e.stopPropagation();
        e.preventDefault();
        if (typeof bootstrap !== 'undefined' && bootstrap.Dropdown) {
          const dropdownInstance = bootstrap.Dropdown.getOrCreateInstance(packagesLink);
          dropdownInstance.toggle();
        }
      });
    }

    // Click on link itself (but not text or caret) -> navigate
    packagesLink.addEventListener('click', (e) => {
      // If click is on text or caret, let their handlers deal with it
      if (
        e.target === packagesText ||
        e.target === caretIcon ||
        packagesText?.contains(e.target) ||
        caretIcon?.contains(e.target)
      ) {
        return;
      }
      // Otherwise navigate
      window.location.href = '/package';
    });
  }

  // Run on DOM ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initPackagesMenu);
  } else {
    initPackagesMenu();
  }

  // Also run after Bootstrap loads
  window.addEventListener('bootstrapScriptLoaded', initPackagesMenu);
  setTimeout(initPackagesMenu, 500);
  setTimeout(initPackagesMenu, 1000);
})();

