// Desktop: static Popper for top-level mega menus (including Others) so CSS left/right wins.
(function () {
  function syncMainNavDropdownPopper() {
    if (typeof bootstrap === 'undefined' || !bootstrap.Dropdown) return;
    var desktop =
      typeof window.matchMedia === 'function' &&
      window.matchMedia('(min-width: 992px)').matches;
    document
      .querySelectorAll('#main-navigation [data-bs-toggle="dropdown"]')
      .forEach(function (toggle) {
        if (toggle.closest('.sub-menu-others-level-0')) return;
        try {
          var inst = bootstrap.Dropdown.getInstance(toggle);
          if (inst) inst.dispose();
        } catch (e) {
          /* ignore */
        }
        if (desktop) {
          toggle.setAttribute('data-bs-popper', 'static');
        } else {
          toggle.removeAttribute('data-bs-popper');
        }
        try {
          new bootstrap.Dropdown(toggle);
        } catch (e2) {
          /* ignore */
        }
      });
  }

  window.addEventListener('bootstrapScriptLoaded', function () {
    setTimeout(syncMainNavDropdownPopper, 0);
  });
  var resizeTimer;
  window.addEventListener('resize', function () {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(syncMainNavDropdownPopper, 200);
  });
})();

// Others mega: Popper/Bootstrap can overwrite `transform` inline after open; re-apply shift with !important.
(function () {
  function initOthersDropdownShift() {
    var toggle = document.getElementById('nav-link-others-level-0');
    var menu = document.getElementById('sub-menu-others-level-0');
    if (!toggle || !menu || toggle.dataset.othersShiftInit === '1') return;
    toggle.dataset.othersShiftInit = '1';

    function isDesktopMega() {
      return (
        typeof window.matchMedia === 'function' &&
        window.matchMedia('(min-width: 992px)').matches
      );
    }

    function applyShift() {
      if (!menu.classList.contains('show')) return;
      if (!isDesktopMega()) {
        menu.style.removeProperty('transform');
        return;
      }
      /* Align with dropdown-menu-end + content-sized Others panel (see OthersMenu.astro). */
      menu.style.setProperty('transform', 'translateX(0)', 'important');
    }

    function clearShift() {
      menu.style.removeProperty('transform');
    }

    toggle.addEventListener('shown.bs.dropdown', function () {
      applyShift();
      requestAnimationFrame(applyShift);
      setTimeout(applyShift, 0);
      setTimeout(applyShift, 80);
    });
    toggle.addEventListener('hidden.bs.dropdown', clearShift);
    window.addEventListener('resize', function () {
      if (menu.classList.contains('show')) applyShift();
      else clearShift();
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initOthersDropdownShift);
  } else {
    initOthersDropdownShift();
  }
  window.addEventListener('bootstrapScriptLoaded', function () {
    setTimeout(initOthersDropdownShift, 0);
  });
})();

// Fix for horizontal scroll - ensure scroll-content exists before JS runs
(function () {
  function fixHorizontalScroll() {
    document.querySelectorAll('.horizontal-scroll').forEach(function (container) {
      var scrollContent = container.querySelector('.scroll-content');
      if (!scrollContent) {
        // Create scroll-content if it doesn't exist
        var wrapper = document.createElement('div');
        wrapper.className =
          'scroll-content d-flex pt-16 pb-16 gap-column-16 has-gap-column scroll-content-element';

        // Move existing children into scroll-content
        while (container.firstChild) {
          wrapper.appendChild(container.firstChild);
        }

        container.appendChild(wrapper);
      }
    });
  }

  // Run immediately if DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', fixHorizontalScroll);
  } else {
    fixHorizontalScroll();
  }

  // Also run after main script loads
  window.addEventListener('bootstrapScriptLoaded', function () {
    setTimeout(fixHorizontalScroll, 100);
  });

  // Run after a delay to catch late-loading elements
  setTimeout(fixHorizontalScroll, 500);
  setTimeout(fixHorizontalScroll, 1000);
})();

